import Page11 from './pages/Page11.jsx';
import Page12 from './pages/Page12.jsx';
const pages={"demo-corporate-2":Page0,"demo-corporate-2-about":Page1,"demo-corporate-2-article":Page2,"demo-corporate-2-careers":Page3,"demo-corporate-2-case-studies":Page4,"demo-corporate-2-case-study":Page5,"demo-corporate-2-contact":Page6,"demo-corporate-2-faq":Page7,"demo-corporate-2-insights":Page8,"demo-corporate-2-pricing":Page9,"demo-corporate-2-service":Page10,"demo-corporate-2-services":Page11,"demo-corporate-2-team":Page12};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-corporate-2");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-corporate-2");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

